function PendingRequests(){ return <ConsoleShell path="/pending-requests"><section className="cx-panel"><header><div><span className="mono">DEVELOPER CHANGE REQUESTS</span><h2>รายการคำขอ</h2></div></header><Toolbar search="ค้นหา request ID หรือ subsystem"/><div className="cx-diff-empty"><ArrowLeftRight/><strong>ไม่มีคำขอที่รอตัดสินใจ</strong><span className="mono">old → new diff will appear here</span></div></section></ConsoleShell> }

